import{_ as e,o as l,c as i,a5 as t}from"./chunks/framework.BPFk9-tb.js";const u=JSON.parse('{"title":"《原则2：应对变化中的世界秩序》读书笔记","description":"","frontmatter":{"date":"2022-06-02T09:00:49","title":"《原则2：应对变化中的世界秩序》读书笔记","categories":["写作","作业","原则"],"tags":["写作","作业","原则"]},"headers":[{"level":2,"title":"在作者看来，三个最重要的周期分别是什么？","slug":"在作者看来-三个最重要的周期分别是什么","link":"#在作者看来-三个最重要的周期分别是什么","children":[]},{"level":2,"title":"典型的大周期分为几个阶段？你所在的国家正处在哪个阶段？","slug":"典型的大周期分为几个阶段-你所在的国家正处在哪个阶段","link":"#典型的大周期分为几个阶段-你所在的国家正处在哪个阶段","children":[]},{"level":2,"title":"三大周期、国家及其货币兴衰的3、5、8和18个决定因素是什么？","slug":"三大周期、国家及其货币兴衰的3、5、8和18个决定因素是什么","link":"#三大周期、国家及其货币兴衰的3、5、8和18个决定因素是什么","children":[]},{"level":2,"title":"长期债务周期包括几个阶段？各个阶段特点是什么？央行和政府在其中扮演着什么角色？思考为什么不应该依靠政府保护你的钱财？","slug":"长期债务周期包括几个阶段-各个阶段特点是什么-央行和政府在其中扮演着什么角色-思考为什么不应该依靠政府保护你的钱财","link":"#长期债务周期包括几个阶段-各个阶段特点是什么-央行和政府在其中扮演着什么角色-思考为什么不应该依靠政府保护你的钱财","children":[]},{"level":2,"title":"三种类型的货币体系分别是什么？彼此之间是如何转换的？","slug":"三种类型的货币体系分别是什么-彼此之间是如何转换的","link":"#三种类型的货币体系分别是什么-彼此之间是如何转换的","children":[]},{"level":2,"title":"所有货币都出现过贬值，货币贬值具有哪些共性？","slug":"所有货币都出现过贬值-货币贬值具有哪些共性","link":"#所有货币都出现过贬值-货币贬值具有哪些共性","children":[]},{"level":2,"title":"作者发现，在大多数国家，虽然人们会在意识形态和宗教方面发生争斗，但影响大多数人的最重要因素是？","slug":"作者发现-在大多数国家-虽然人们会在意识形态和宗教方面发生争斗-但影响大多数人的最重要因素是","link":"#作者发现-在大多数国家-虽然人们会在意识形态和宗教方面发生争斗-但影响大多数人的最重要因素是","children":[]},{"level":2,"title":"内部秩序和混乱大周期包括几个阶段？哪些信号表明美国处于第五个阶段（财政状况糟糕、冲突激烈）？","slug":"内部秩序和混乱大周期包括几个阶段-哪些信号表明美国处于第五个阶段-财政状况糟糕、冲突激烈","link":"#内部秩序和混乱大周期包括几个阶段-哪些信号表明美国处于第五个阶段-财政状况糟糕、冲突激烈","children":[]},{"level":2,"title":"外部秩序变化背后的永恒普适力量是什么？","slug":"外部秩序变化背后的永恒普适力量是什么","link":"#外部秩序变化背后的永恒普适力量是什么","children":[]},{"level":2,"title":"从投资者的角度来看大周期的整体格局，大多数投资者面临的三大风险是什么？","slug":"从投资者的角度来看大周期的整体格局-大多数投资者面临的三大风险是什么","link":"#从投资者的角度来看大周期的整体格局-大多数投资者面临的三大风险是什么","children":[]},{"level":2,"title":"荷兰帝国兴起的过程中，两个最重要的发明是什么？为何衰退？","slug":"荷兰帝国兴起的过程中-两个最重要的发明是什么-为何衰退","link":"#荷兰帝国兴起的过程中-两个最重要的发明是什么-为何衰退","children":[]},{"level":2,"title":"大英帝国是如何取代荷兰帝国，成为新兴帝国的？如何衰退？","slug":"大英帝国是如何取代荷兰帝国-成为新兴帝国的-如何衰退","link":"#大英帝国是如何取代荷兰帝国-成为新兴帝国的-如何衰退","children":[]},{"level":2,"title":"美帝国是如何兴起并走向顶峰取代大英帝国，成为新兴帝国的？","slug":"美帝国是如何兴起并走向顶峰取代大英帝国-成为新兴帝国的","link":"#美帝国是如何兴起并走向顶峰取代大英帝国-成为新兴帝国的","children":[]},{"level":2,"title":"美国在自身大周期中所处的位置是？哪些典型的标志和信号？","slug":"美国在自身大周期中所处的位置是-哪些典型的标志和信号","link":"#美国在自身大周期中所处的位置是-哪些典型的标志和信号","children":[]},{"level":2,"title":"为什么帝国的衰退不可避免？（无论荷兰、英国还是美国）","slug":"为什么帝国的衰退不可避免-无论荷兰、英国还是美国","link":"#为什么帝国的衰退不可避免-无论荷兰、英国还是美国","children":[]},{"level":2,"title":"从1949到现在的崛起，可以把中国发展分为几个阶段？","slug":"从1949到现在的崛起-可以把中国发展分为几个阶段","link":"#从1949到现在的崛起-可以把中国发展分为几个阶段","children":[]},{"level":2,"title":"中美关系为何从共生关系走向冲突？","slug":"中美关系为何从共生关系走向冲突","link":"#中美关系为何从共生关系走向冲突","children":[]},{"level":2,"title":"美国和中国的现状分别是？有几种类型的战争？","slug":"美国和中国的现状分别是-有几种类型的战争","link":"#美国和中国的现状分别是-有几种类型的战争","children":[]},{"level":2,"title":"作者对于未来的观点是基于作者对进化、周期、指标三点的想法，分别是？","slug":"作者对于未来的观点是基于作者对进化、周期、指标三点的想法-分别是","link":"#作者对于未来的观点是基于作者对进化、周期、指标三点的想法-分别是","children":[]},{"level":2,"title":"基于对过去的分析和未来的预测，达利欧建议应该如何应对已知和未知？有哪几条原则？","slug":"基于对过去的分析和未来的预测-达利欧建议应该如何应对已知和未知-有哪几条原则","link":"#基于对过去的分析和未来的预测-达利欧建议应该如何应对已知和未知-有哪几条原则","children":[]}],"relativePath":"posts/homework/129.md","filePath":"posts/homework/129.md"}'),r={name:"posts/homework/129.md"};function h(n,a,o,p,d,s){return l(),i("div",null,[...a[0]||(a[0]=[t('<p>4月定投课堂读书会的书目是《原则2：应对变化中的世界秩序》。知道如何应对我所不知道的东西。</p><h1 id="第一周" tabindex="-1">第一周 <a class="header-anchor" href="#第一周" aria-label="Permalink to &quot;第一周&quot;">​</a></h1><h2 id="在作者看来-三个最重要的周期分别是什么" tabindex="-1">在作者看来，三个最重要的周期分别是什么？ <a class="header-anchor" href="#在作者看来-三个最重要的周期分别是什么" aria-label="Permalink to &quot;在作者看来，三个最重要的周期分别是什么？&quot;">​</a></h2><p>长期债务和资本市场周期、内部秩序和混乱周期、外部秩序和混乱周期</p><h2 id="典型的大周期分为几个阶段-你所在的国家正处在哪个阶段" tabindex="-1">典型的大周期分为几个阶段？你所在的国家正处在哪个阶段？ <a class="header-anchor" href="#典型的大周期分为几个阶段-你所在的国家正处在哪个阶段" aria-label="Permalink to &quot;典型的大周期分为几个阶段？你所在的国家正处在哪个阶段？&quot;">​</a></h2><p>上升阶段、顶部阶段和下跌阶段。目前处于上升阶段阶段。</p><h2 id="三大周期、国家及其货币兴衰的3、5、8和18个决定因素是什么" tabindex="-1">三大周期、国家及其货币兴衰的3、5、8和18个决定因素是什么？ <a class="header-anchor" href="#三大周期、国家及其货币兴衰的3、5、8和18个决定因素是什么" aria-label="Permalink to &quot;三大周期、国家及其货币兴衰的3、5、8和18个决定因素是什么？&quot;">​</a></h2><p>3个决定因素：有利和不利的金融周期、内部秩序和混乱的周期、外部秩序和混乱周期</p><p>5个决定因素：有利和不利的金融周期、内部秩序和混乱的周期、外部秩序和混乱周期、创新和技术、天灾</p><p>8个决定因素：教育，竞争力，创新和技术、经济产出、世界贸易份额、军事实力、金融中心实力、储备货币地位。</p><p>18个决定因素：3大周期（经济大周期、内部秩序和混乱周期、外部秩序和混乱周期），8个实力指标（教育、创新和技术、成本竞争力、军事实力、贸易、经济产出、市场和金融中心、储备货币地位），7个额外因素（地质、资源分配效率、自然现象、基础设施和投资、品格/教养/决心，国家治理/法规，财富机会和价值观差距）</p><h2 id="长期债务周期包括几个阶段-各个阶段特点是什么-央行和政府在其中扮演着什么角色-思考为什么不应该依靠政府保护你的钱财" tabindex="-1">长期债务周期包括几个阶段？各个阶段特点是什么？央行和政府在其中扮演着什么角色？思考为什么不应该依靠政府保护你的钱财？ <a class="header-anchor" href="#长期债务周期包括几个阶段-各个阶段特点是什么-央行和政府在其中扮演着什么角色-思考为什么不应该依靠政府保护你的钱财" aria-label="Permalink to &quot;长期债务周期包括几个阶段？各个阶段特点是什么？央行和政府在其中扮演着什么角色？思考为什么不应该依靠政府保护你的钱财？&quot;">​</a></h2><p>6个阶段：</p><p>1.最初a）并不存在债务，或者债务很少，b）人们使用硬通货；</p><p>2.后来出现了硬通货债券票据；</p><p>3）后来是债务增加；</p><p>4）然后会发生债务危机、违约和货币贬值，导致印钞和与硬通货脱钩；</p><p>5）然后是法定货币，最终导致贬值；</p><p>6）回归硬通货。</p><p>大多数政府会滥用它们作为货币和信贷创造者与使用者的特权；没有任何一个决策者能够掌控整个长期债务周期。</p><h2 id="三种类型的货币体系分别是什么-彼此之间是如何转换的" tabindex="-1">三种类型的货币体系分别是什么？彼此之间是如何转换的？ <a class="header-anchor" href="#三种类型的货币体系分别是什么-彼此之间是如何转换的" aria-label="Permalink to &quot;三种类型的货币体系分别是什么？彼此之间是如何转换的？&quot;">​</a></h2><p>三种类型的货币体系是硬通货，纸币，法定货币。</p><p>当信誉度最大化，信贷创造最小化的时，从第一类（硬通货）转向第二类（纸币）。</p><p>当信贷创造扩大，信誉度下降时，从第二类（纸币）转向第三类（法定货币）。</p><p>当信贷创造最大化，信誉度最小化时，从第三类（法定货币）回归第一类（硬通货）。</p><h1 id="第二周" tabindex="-1">第二周 <a class="header-anchor" href="#第二周" aria-label="Permalink to &quot;第二周&quot;">​</a></h1><h2 id="所有货币都出现过贬值-货币贬值具有哪些共性" tabindex="-1">所有货币都出现过贬值，货币贬值具有哪些共性？ <a class="header-anchor" href="#所有货币都出现过贬值-货币贬值具有哪些共性" aria-label="Permalink to &quot;所有货币都出现过贬值，货币贬值具有哪些共性？&quot;">​</a></h2><ul><li>所有经济体出现过典型的挤兑现象，即央行发行的债券票据总额超过可提取的硬通货总额。</li><li>央行的的净储备在实际贬值前就已开始减少，在某些央行，甚至在货币贬值前几年就开始减少。</li><li>货币挤兑和贬值的出现通常伴随着严重的债务问题。</li><li>通常来说，央行最初的反应是，提高短期利率，但从经济角度看，这种做法过于痛苦，因此央行很快会放弃这种做法，转而增加货币供应。</li><li>不同国家的结果截然不同，一个重要变量是，该国在货币贬值是保存了多少经济和军事实力</li></ul><h2 id="作者发现-在大多数国家-虽然人们会在意识形态和宗教方面发生争斗-但影响大多数人的最重要因素是" tabindex="-1">作者发现，在大多数国家，虽然人们会在意识形态和宗教方面发生争斗，但影响大多数人的最重要因素是？ <a class="header-anchor" href="#作者发现-在大多数国家-虽然人们会在意识形态和宗教方面发生争斗-但影响大多数人的最重要因素是" aria-label="Permalink to &quot;作者发现，在大多数国家，虽然人们会在意识形态和宗教方面发生争斗，但影响大多数人的最重要因素是？&quot;">​</a></h2><p>影响大多数人的最主要因素是人们如何创造、获取和分配财富与权力。</p><h2 id="内部秩序和混乱大周期包括几个阶段-哪些信号表明美国处于第五个阶段-财政状况糟糕、冲突激烈" tabindex="-1">内部秩序和混乱大周期包括几个阶段？哪些信号表明美国处于第五个阶段（财政状况糟糕、冲突激烈）？ <a class="header-anchor" href="#内部秩序和混乱大周期包括几个阶段-哪些信号表明美国处于第五个阶段-财政状况糟糕、冲突激烈" aria-label="Permalink to &quot;内部秩序和混乱大周期包括几个阶段？哪些信号表明美国处于第五个阶段（财政状况糟糕、冲突激烈）？&quot;">​</a></h2><p>第一阶段，新秩序开始，新领导巩固权力</p><p>第二阶段，资源配置体系与政府官僚机构建立和完善。</p><p>第三阶段，出现和平与繁荣。</p><p>第四阶段，支出和债务严重过度，贫富差距和政治分歧扩大。</p><p>第五阶段，财政状况糟糕，冲突激烈</p><p>第六阶段，出现内战/革命。</p><p>在今天的美国，联邦政府及许多州和城市的政府面临着巨额赤字、巨额债务和巨大的贫富差距，美联储正在大规模增印货币，购买大量联邦政府债券，为联邦政府支出提供资金，而目前联邦政府的支出远大于收入。</p><h2 id="外部秩序变化背后的永恒普适力量是什么" tabindex="-1">外部秩序变化背后的永恒普适力量是什么？ <a class="header-anchor" href="#外部秩序变化背后的永恒普适力量是什么" aria-label="Permalink to &quot;外部秩序变化背后的永恒普适力量是什么？&quot;">​</a></h2><p>国内实力和军事实力密切相关。</p><p>在财力上超过对手是一个国家能够拥有的最大优势之一。</p><p>在以下两种情况下，爆发军事战争的风险最大：1）双方的军事实力旗鼓相当，2）双方在生存问题上存在不可调和的分歧。</p><p>要想获取更多的双赢结果，双方必须进行良好的协商，既考虑到对方也考虑到自身的优先关注点，并懂得妥善的在二者之间进行权衡。</p><p>获胜意味着在不失去最重要的东西的前提下，得到最重要的东西。所以，如果丧失的生命和金钱超过带来的益处，这样的战争就是愚蠢的。</p><p>获取权力，尊重权利，并明智的运用权力。</p><h2 id="从投资者的角度来看大周期的整体格局-大多数投资者面临的三大风险是什么" tabindex="-1">从投资者的角度来看大周期的整体格局，大多数投资者面临的三大风险是什么？ <a class="header-anchor" href="#从投资者的角度来看大周期的整体格局-大多数投资者面临的三大风险是什么" aria-label="Permalink to &quot;从投资者的角度来看大周期的整体格局，大多数投资者面临的三大风险是什么？&quot;">​</a></h2><p>大多数投资者面临的三大风险是，投资组合将无法提供支出所需的回报，投资组合将面临破产，以及很大一部分财富会被收走。</p><h1 id="第三周" tabindex="-1">第三周 <a class="header-anchor" href="#第三周" aria-label="Permalink to &quot;第三周&quot;">​</a></h1><h2 id="荷兰帝国兴起的过程中-两个最重要的发明是什么-为何衰退" tabindex="-1">荷兰帝国兴起的过程中，两个最重要的发明是什么？为何衰退？ <a class="header-anchor" href="#荷兰帝国兴起的过程中-两个最重要的发明是什么-为何衰退" aria-label="Permalink to &quot;荷兰帝国兴起的过程中，两个最重要的发明是什么？为何衰退？&quot;">​</a></h2><p>荷兰人的两个最重要的发明是：1）效能及其优异的帆船，使他们能在世界各地航行，这一点再加上他们从欧洲战事中获得的军事能力，使他们能收集巨大的财富；2）为这些行动提供推动力的资本主义。</p><p>负债过多，国内发生许多财富争斗，军事实力衰落，受到英国的挑战，荷兰盾贬值，失去储备货币地位。</p><h2 id="大英帝国是如何取代荷兰帝国-成为新兴帝国的-如何衰退" tabindex="-1">大英帝国是如何取代荷兰帝国，成为新兴帝国的？如何衰退？ <a class="header-anchor" href="#大英帝国是如何取代荷兰帝国-成为新兴帝国的-如何衰退" aria-label="Permalink to &quot;大英帝国是如何取代荷兰帝国，成为新兴帝国的？如何衰退？&quot;">​</a></h2><p>对法制的尊重，有力的教育，为英国在商业和创新方面取得竞争优势奠定了基础。受过良好教育的人口，重视发明创造的文化，新想法的发展能够得到资本的经济支持，这些因素创造了一大波竞争力提升与繁荣。英国的军事实力，特别是海军、帮助它建立殖民地，多去其他欧洲国家的殖民地，并确保对全球贸易路线的控制。伦敦成为世界金融中心，英镑成为世界储备货币。</p><p>竞争力下降，不平等和冲突加剧，新的竞争对手崛起，特别是德国和美国。二战后英国背负沉重债务，维持帝国的代价高于盈利，英镑贬值，失去国际储备货币地位。</p><h2 id="美帝国是如何兴起并走向顶峰取代大英帝国-成为新兴帝国的" tabindex="-1">美帝国是如何兴起并走向顶峰取代大英帝国，成为新兴帝国的？ <a class="header-anchor" href="#美帝国是如何兴起并走向顶峰取代大英帝国-成为新兴帝国的" aria-label="Permalink to &quot;美帝国是如何兴起并走向顶峰取代大英帝国，成为新兴帝国的？&quot;">​</a></h2><p>美国通过革命建立了一个新的国内秩序，第二次工业革命创造了收入、技术和财富的巨大收益。二次世界大战美国都是大赢家。</p><h2 id="美国在自身大周期中所处的位置是-哪些典型的标志和信号" tabindex="-1">美国在自身大周期中所处的位置是？哪些典型的标志和信号？ <a class="header-anchor" href="#美国在自身大周期中所处的位置是-哪些典型的标志和信号" aria-label="Permalink to &quot;美国在自身大周期中所处的位置是？哪些典型的标志和信号？&quot;">​</a></h2><p>作者分析美国在自身大周期中处于第五阶段（约处于大周期70%的位置，误差范围为10个百分点）。</p><p>三个重要的标志：1）规则被无视，2）双方相互的情绪化攻击，3）发生流血事件。</p><h2 id="为什么帝国的衰退不可避免-无论荷兰、英国还是美国" tabindex="-1">为什么帝国的衰退不可避免？（无论荷兰、英国还是美国） <a class="header-anchor" href="#为什么帝国的衰退不可避免-无论荷兰、英国还是美国" aria-label="Permalink to &quot;为什么帝国的衰退不可避免？（无论荷兰、英国还是美国）&quot;">​</a></h2><p>让帝国强大的力量减弱，敌对力量出现。</p><h1 id="第四周" tabindex="-1">第四周 <a class="header-anchor" href="#第四周" aria-label="Permalink to &quot;第四周&quot;">​</a></h1><h2 id="从1949到现在的崛起-可以把中国发展分为几个阶段" tabindex="-1">从1949到现在的崛起，可以把中国发展分为几个阶段？ <a class="header-anchor" href="#从1949到现在的崛起-可以把中国发展分为几个阶段" aria-label="Permalink to &quot;从1949到现在的崛起，可以把中国发展分为几个阶段？&quot;">​</a></h2><p>可以分为三个阶段，1949～1976，1978～2008，2008年至今</p><h2 id="中美关系为何从共生关系走向冲突" tabindex="-1">中美关系为何从共生关系走向冲突？ <a class="header-anchor" href="#中美关系为何从共生关系走向冲突" aria-label="Permalink to &quot;中美关系为何从共生关系走向冲突？&quot;">​</a></h2><p>美国由债务增长支撑的繁荣时期引发了债务泡沫，造成贫富差距，中国实力不断加强，两国从互惠互利的关系变成激烈的竞争关系，冲突加剧。</p><h2 id="美国和中国的现状分别是-有几种类型的战争" tabindex="-1">美国和中国的现状分别是？有几种类型的战争？ <a class="header-anchor" href="#美国和中国的现状分别是-有几种类型的战争" aria-label="Permalink to &quot;美国和中国的现状分别是？有几种类型的战争？&quot;">​</a></h2><p>因为打周期的规律，美国正在衰弱（周期的第五阶段），中国正在崛起（周期的第三阶段）。</p><p>有七大类型的战争：1）贸易/经济战；2）技术战；3）地缘政治战；4）资本战；5）军事战；6）文化战；7）自我交战的战争</p><h2 id="作者对于未来的观点是基于作者对进化、周期、指标三点的想法-分别是" tabindex="-1">作者对于未来的观点是基于作者对进化、周期、指标三点的想法，分别是？ <a class="header-anchor" href="#作者对于未来的观点是基于作者对进化、周期、指标三点的想法-分别是" aria-label="Permalink to &quot;作者对于未来的观点是基于作者对进化、周期、指标三点的想法，分别是？&quot;">​</a></h2><p>人类的创造性可能会带来更大的进步，但同时债务/经济周期、内部秩序和混乱周期、外部秩序和混乱周期与不断恶化的自然灾害，几乎可以肯定会构成问题。换言之，人类的创造性和这些其他挑战，将存在一场斗争。</p><p>各国内部和各国之间情况极为不同，这将决定哪些国家将以何种方式崛起，哪些国家将以何种方式衰弱。</p><h2 id="基于对过去的分析和未来的预测-达利欧建议应该如何应对已知和未知-有哪几条原则" tabindex="-1">基于对过去的分析和未来的预测，达利欧建议应该如何应对已知和未知？有哪几条原则？ <a class="header-anchor" href="#基于对过去的分析和未来的预测-达利欧建议应该如何应对已知和未知-有哪几条原则" aria-label="Permalink to &quot;基于对过去的分析和未来的预测，达利欧建议应该如何应对已知和未知？有哪几条原则？&quot;">​</a></h2><p>了解所有的可能性，考虑最坏的情况，然后想办法消除无法忍受的情况。</p><p>分散风险。</p><p>首先考虑延迟满足而不是当下满足，这样你将来会过得更好。</p><p>与最聪明的人反复沟通。</p>',77)])])}const b=e(r,[["render",h]]);export{u as __pageData,b as default};
